create extension if not exists pgcrypto;
create type public.user_role as enum ('student','owner'); create type public.order_status as enum ('submitted','verified','preparing','ready','collected','rejected'); create type public.ticket_status as enum ('waiting','called','done','cancelled');
create table public.profiles(id uuid primary key references auth.users on delete cascade,role user_role not null default 'student',name text not null,roll_no text,branch_year text,phone text,created_at timestamptz default now());
create table public.canteens(id uuid primary key default gen_random_uuid(),owner_id uuid not null references profiles(id),name text not null,location text,opening_hours text,upi_id text not null,qr_image_path text,slot_capacity int not null default 4 check(slot_capacity>0),slot_start time default '12:00',slot_end time default '13:30',slot_interval_minutes int default 10,queue_service_minutes int default 2);
create table public.menu_items(id uuid primary key default gen_random_uuid(),canteen_id uuid not null references canteens(id) on delete cascade,name text not null,price numeric(10,2) not null check(price>=0),emoji text default '🍽️',category text default 'Snacks',is_veg boolean default true,is_available boolean default true,created_at timestamptz default now());
create table public.orders(id uuid primary key default gen_random_uuid(),code text unique not null default 'QB-'||floor(random()*9000+1000)::text,canteen_id uuid not null references canteens,student_id uuid not null references profiles,slot_time text not null,total numeric(10,2) not null,txn_id text not null,status order_status default 'submitted',pickup_pin text not null default lpad(floor(random()*10000)::text,4,'0'),created_at timestamptz default now());
create table public.order_items(order_id uuid references orders on delete cascade,name text not null,emoji text not null,price numeric not null,qty int not null check(qty>0),primary key(order_id,name));
create table public.queue_tickets(id uuid primary key default gen_random_uuid(),canteen_id uuid not null references canteens on delete cascade,student_id uuid not null references profiles,token_no int not null,status ticket_status default 'waiting',joined_ahead_count int default 0,created_at timestamptz default now());
create or replace function public.is_owner_of(cid uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from canteens where id=cid and owner_id=auth.uid())$$;
alter table profiles enable row level security; alter table canteens enable row level security; alter table menu_items enable row level security; alter table orders enable row level security; alter table order_items enable row level security; alter table queue_tickets enable row level security;
create policy profile_self on profiles for all using(id=auth.uid()) with check(id=auth.uid()); create policy canteen_public on canteens for select using(true); create policy canteen_owner on canteens for all using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy menu_public on menu_items for select using(is_available or is_owner_of(canteen_id)); create policy menu_owner on menu_items for all using(is_owner_of(canteen_id)) with check(is_owner_of(canteen_id));
create policy order_read on orders for select using(student_id=auth.uid() or is_owner_of(canteen_id)); create policy order_insert on orders for insert with check(student_id=auth.uid()); create policy order_update on orders for update using(is_owner_of(canteen_id)); create policy item_read on order_items for select using(exists(select 1 from orders o where o.id=order_id and (o.student_id=auth.uid() or is_owner_of(o.canteen_id)))); create policy ticket_access on queue_tickets for all using(student_id=auth.uid() or is_owner_of(canteen_id)) with check(student_id=auth.uid());
create or replace function public.book_order(p_canteen uuid,p_slot text,p_total numeric,p_txn text,p_items jsonb) returns uuid language plpgsql security definer set search_path=public as $$declare oid uuid; cap int; used int; begin select slot_capacity into cap from canteens where id=p_canteen for update; select count(*) into used from orders where canteen_id=p_canteen and slot_time=p_slot and status<>'rejected'; if used>=cap then raise exception 'slot_full'; end if; insert into orders(canteen_id,student_id,slot_time,total,txn_id) values(p_canteen,auth.uid(),p_slot,p_total,p_txn) returning id into oid; insert into order_items select oid,x.name,x.emoji,x.price,x.qty from jsonb_to_recordset(p_items) x(name text,emoji text,price numeric,qty int); return oid; end $$;
create or replace function public.join_queue(p_canteen uuid) returns queue_tickets language plpgsql security definer set search_path=public as $$declare t queue_tickets; n int; ahead int; begin select coalesce(max(token_no),0)+1 into n from queue_tickets where canteen_id=p_canteen and created_at::date=current_date; select count(*) into ahead from queue_tickets where canteen_id=p_canteen and created_at::date=current_date and status='waiting'; insert into queue_tickets(canteen_id,student_id,token_no,joined_ahead_count) values(p_canteen,auth.uid(),n,ahead) returning * into t; return t; end $$;
alter publication supabase_realtime add table public.orders,public.queue_tickets; insert into storage.buckets(id,name,public) values('payment-qr','payment-qr',true),('menu-uploads','menu-uploads',false) on conflict do nothing;
